// Value: protects=saving or editing a result revalidates /sessions/{id} of the session the RPC returns, the only re-render of the session page now;
// fails_when=revalidateSessionRoutes is dropped or keyed off the wrong id, so a saved score stays blank until a manual reload;
// why_new=no test ran session-result-actions; component tests mock it and the editor's router.refresh() was removed; seam=none;
// no_claim=supabase, permissions and next/cache are mocked; does not prove Next re-renders the page
import { beforeEach, describe, expect, it, vi } from "vitest";

const rpcMock = vi.hoisted(() => vi.fn());
const permissionsMock = vi.hoisted(() => vi.fn());

vi.mock("@/lib/permissions/database-permissions", () => ({
  getDatabasePermissions: permissionsMock,
}));

vi.mock("@/lib/supabase/server", () => ({
  createSupabaseServerClient: vi.fn(async () => ({
    rpc: rpcMock,
  })),
}));

vi.mock("next/cache", () => ({
  revalidatePath: vi.fn(),
}));

import { revalidatePath } from "next/cache";

import {
  recordSessionResultAction,
  updateSessionResultAction,
} from "@/features/sessions/actions/session-result-actions";

describe("session result actions page refresh", () => {
  const classSessionId = "fa70d806-18e0-4b04-af6e-b045156a13fa";
  const resultId = "5d1f0a8e-2b7c-4c3d-9e8f-1a2b3c4d5e6f";
  const saved = { data: { class_session_id: classSessionId, id: resultId }, error: null };

  beforeEach(() => {
    rpcMock.mockReset();
    vi.mocked(revalidatePath).mockClear();
    permissionsMock.mockResolvedValue({ ok: true, permissions: ["results.manage"] });
  });

  it("revalidates the session page after a new result is recorded", async () => {
    rpcMock.mockResolvedValueOnce(saved);

    await expect(recordSessionResultAction({
      classSessionId,
      comment: "Con làm bài cẩn thận.",
      notebookScore: null,
      notebookStatus: "not_submitted",
      studentId: "0b3c1a52-7d4e-4f1a-9a3b-2c5d6e7f8a90",
      testScore: 8.5,
    })).resolves.toMatchObject({ classSessionId, resultId, status: "success" });

    expect(rpcMock).toHaveBeenCalledWith("record_session_result", expect.objectContaining({ p_class_session_id: classSessionId }));
    expect(revalidatePath).toHaveBeenCalledWith(`/sessions/${classSessionId}`);
  });

  it("revalidates the session page the RPC returns after a result is edited", async () => {
    rpcMock.mockResolvedValueOnce(saved);

    await expect(updateSessionResultAction({
      comment: null,
      notebookScore: 9,
      notebookStatus: "submitted",
      reason: "Chấm lại bài kiểm tra",
      resultId,
      testScore: 7,
    })).resolves.toMatchObject({ classSessionId, resultId, status: "success" });

    expect(rpcMock).toHaveBeenCalledWith("update_session_result", expect.objectContaining({ p_session_result_id: resultId }));
    expect(revalidatePath).toHaveBeenCalledWith(`/sessions/${classSessionId}`);
  });
});
